package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.WebauthnEnabledVO;

class WebauthnEnabledValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of webauthn enabled of tenant config")
  void test_webauthn_enabled_value_holder_assign_plain_value() {
    Object holder = new Object();
    WebauthnEnabledValueHolder<Object> value = new WebauthnEnabledValueHolder<>(holder);
    Assertions.assertSame(holder, value.webauthnEnabled(true), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnEnabledValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getWebauthnEnabled().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.webauthnEnabledNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnEnabledValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of webauthn enabled of tenant config")
  void test_webauthn_enabled_value_holder_assign_value_object() {
    Object holder = new Object();
    WebauthnEnabledValueHolder<Object> value = new WebauthnEnabledValueHolder<>(holder);
    WebauthnEnabledVO vo = WebauthnEnabledVO.from(true);
    Assertions.assertFalse(value.getWebauthnEnabledValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.webauthnEnabled(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWebauthnEnabledValue().orElseThrow());
    Assertions.assertSame(holder, value.webauthnEnabled(Optional.empty()));
    Assertions.assertFalse(value.getWebauthnEnabledValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.webauthnEnabled(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWebauthnEnabledValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of webauthn enabled of tenant config against the original")
  void test_webauthn_enabled_value_holder_read() {
    Object holder = new Object();
    WebauthnEnabledValueHolder<Object> value = new WebauthnEnabledValueHolder<>(holder);
    WebauthnEnabledVO vo = WebauthnEnabledVO.from(true);
    WebauthnEnabledVO other = WebauthnEnabledVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getWebauthnEnabledValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWebauthnEnabled(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWebauthnEnabled(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.webauthnEnabled(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWebauthnEnabled(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWebauthnEnabled(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of webauthn enabled of tenant config")
  void test_webauthn_enabled_value_holder_unset() {
    Object holder = new Object();
    WebauthnEnabledValueHolder<Object> value = new WebauthnEnabledValueHolder<>(holder);
    WebauthnEnabledVO vo = WebauthnEnabledVO.from(true);
    value.webauthnEnabled(vo);
    Assertions.assertSame(holder, value.unsetWebauthnEnabledIfMatches("webauthnEnabled_other"));
    Assertions.assertTrue(value.getWebauthnEnabledValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWebauthnEnabledIfMatches("webauthnEnabled"));
    Assertions.assertFalse(value.getWebauthnEnabledValue().isPresent(),
        "The field name must clear the value");
    value.webauthnEnabled(vo);
    Assertions.assertSame(holder, value.unsetWebauthnEnabled());
    Assertions.assertFalse(value.getWebauthnEnabledValue().isPresent(),
        "Unset must clear the value");
  }
}
